def A(k):
    # k must be a divisor of 1000, and k >= 2
    if 1000 % k != 0 or k < 2:
        return -1
    m = 1000 // k
    if m < 2:
        # This only happens if k > 500, which is covered by k being a divisor of 1000, except for k=1000, m=1
        return -1
    return (m - 1) * (k - 1)

# Divisors of 1000: 1, 2, 4, 5, 8, 10, 20, 25, 40, 50, 100, 125, 200, 250, 500, 1000
divisors = [d for d in range(2, 1001) if 1000 % d == 0]
max_A = 0
for k in divisors:
    current_A = A(k)
    if current_A > max_A:
        max_A = current_A

print(f"Maximum A found in this construction: {max_A}")
